package dk.jamesbabz.madkursus.inbound.rest.recipetemplate;
import java.net.URI;import java.util.*;import dk.jamesbabz.madkursus.inbound.rest.RecipeTemplateApiDelegate;import dk.jamesbabz.madkursus.inbound.rest.dto.*;import dk.jamesbabz.madkursus.inbound.rest.recipe.RecipeRestMapper;import dk.jamesbabz.madkursus.service.applications.RecipeTemplateService;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class RecipeTemplateApiDelegateImpl implements RecipeTemplateApiDelegate{private final RecipeTemplateService service;private final RecipeTemplateRestMapper mapper;private final RecipeRestMapper recipes;public ResponseEntity<List<RecipeTemplateSummaryDTO>>getRecipeTemplates(String query){return ResponseEntity.ok(service.search(query).stream().map(mapper::summary).toList());}public ResponseEntity<RecipeTemplateDTO>getRecipeTemplate(UUID id,Integer portions){return ResponseEntity.ok(mapper.detail(service.getRendered(id,portions==null?1:portions)));}public ResponseEntity<RecipeDTO>addRecipeTemplateToMyRecipes(UUID id){RecipeDTO result=recipes.toDto(service.copy(id));return ResponseEntity.created(URI.create("/v1/recipes/"+result.getId())).body(result);}}
